+'use strict';
+
+function pageCount(total, perPage) {
+  if (total <= 0) return 0;
+  return Math.floor(total / perPage);
+}
+
+function pageSlice(items, page, perPage) {
+  const start = (page - 1) * perPage;
+  return items.slice(start, start + perPage);
+}
+
+module.exports = { pageCount, pageSlice };
