+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { pageCount, pageSlice } = require('../lib/page');
+
+test('pageCount of an exact multiple', () => assert.equal(pageCount(100, 50), 2));
+test('pageCount of zero', () => assert.equal(pageCount(0, 50), 0));
+test('pageSlice second page', () => {
+  const items = Array.from({ length: 120 }, (_, i) => i);
+  assert.deepEqual(pageSlice(items, 2, 50)[0], 50);
+});
